# OMF names are at most 255 bytes. A longer symbol name keeps its first 238
# bytes and gets '$' and a hash of the whole name, the same in every module:
# a COMDAT, a public and the EXTDEFs that reach them by the long name still
# match, and names that differ only after the first 238 bytes stay apart.
# RUN: llvm-mc -triple=i8086-pc-msdos -filetype=obj %s -o %t.obj
# RUN: %python %S/Inputs/omfdump.py %t.obj | FileCheck %s

# CHECK:      EXTDEF '[[EXT:_e{237}\$[0-9A-F]{16}]]' type=0
# CHECK:      PUBDEF '[[PUB:_p{237}\$[0-9A-F]{16}]]'
# CHECK:      LNAMES {{.*}}='[[INL:_i{237}\$[0-9A-F]{16}]]' {{.*}}='[[INL2:_i{237}\$[0-9A-F]{16}]]'
# CHECK-NEXT: COMDAT '[[INL]]' flags=00 attr=10
# CHECK:      COMDAT '[[INL2]]' flags=00 attr=10
# CHECK:      MODEND


